<script setup lang="ts">
import {ref,watch} from 'vue';
import {api,date,type ReviewSnapshot} from '../api/client';
import {useWorkLoad} from '../lib/workLoad';
import {useSession} from '../stores/session';
import {useFieldErrors} from '../lib/fieldErrors';
import PageState from './PageState.vue';
import PublicReviews from './PublicReviews.vue';
const props=defineProps<{orderId:string}>(),session=useSession();
const {data,loading,error,reload}=useWorkLoad(()=>api<ReviewSnapshot>('/orders/'+encodeURIComponent(props.orderId)+'/reviews'));
const stars=ref(0),comment=ref(''),confirm=ref(false),busy=ref(false),submitError=ref('');
const {fields,clear,flag,attributes}=useFieldErrors();let epoch=0;
watch(()=>session.user?.id,()=>{epoch++;stars.value=0;comment.value='';confirm.value=false;submitError.value='';busy.value=false;clear()},{flush:'sync'});
function prepare(){clear();submitError.value='';if(!stars.value)return flag('review-star-1','请选择1至5星评分');if(!comment.value.trim())return flag('review-comment','请填写评价内容');if(Array.from(comment.value.trim()).length>500)return flag('review-comment','评价内容最多500字');confirm.value=true}
async function submit(){const generation=epoch;busy.value=true;submitError.value='';try{await api('/orders/'+encodeURIComponent(props.orderId)+'/reviews','POST',{stars:stars.value,comment:comment.value.trim()});if(generation!==epoch)return;confirm.value=false;await reload();window.dispatchEvent(new Event('market:changed'))}catch(failure){if(generation!==epoch)return;submitError.value=failure instanceof Error?failure.message:'评价提交失败';await reload()}finally{if(generation===epoch)busy.value=false}}
</script>
<template><section class="panel stack" aria-label="交易评价"><div class="row spread"><h2>交易评价</h2><button class="text-button" :disabled="loading" @click="reload()">刷新评价</button></div><PageState :loading="loading" :error="error" @retry="reload"><template v-if="data"><p v-if="data.deadline" class="muted">评价截止 {{date(data.deadline)}}</p><section v-if="data.ownReview" class="stack section-divider" aria-label="我的评价"><div class="row spread"><h3>我的评价</h3><span class="status">{{data.ownReview.publishedAt?'已公开':'待公开'}}</span></div><p>{{data.ownReview.stars}} / 5 星</p><p class="preserve">{{data.ownReview.comment}}</p><p class="muted">提交后不可修改。双方均提交或评价期结束后公开。</p></section><form v-else-if="data.eligible" class="stack section-divider" @submit.prevent="prepare"><p class="muted">双方评价公开后分别计入买家和卖家信用。未评价不自动计分。</p><fieldset class="star-picker"><legend>评分 <span class="required">必填</span></legend><label v-for="star in [1,2,3,4,5]" :key="star"><input :id="'review-star-'+star" v-model="stars" type="radio" name="review-stars" :value="star" v-bind="attributes('review-star-1')"/><span>{{star}} 星</span></label></fieldset><p v-if="fields['review-star-1']" id="review-star-1-error" class="error">{{fields['review-star-1']}}</p><label class="field-label">评价内容 <span class="required">必填</span><textarea id="review-comment" v-model="comment" maxlength="1000" rows="4" v-bind="attributes('review-comment')"/><span v-if="fields['review-comment']" id="review-comment-error" class="error">{{fields['review-comment']}}</span></label><div><button class="button primary" :disabled="busy" type="submit">提交评价</button></div></form><p v-else class="muted">{{data.reason}}</p><div class="section-divider stack"><h3>公开评价</h3><PublicReviews :items="data.items"/></div></template></PageState></section><el-dialog v-model="confirm" title="确认提交评价" width="min(480px, calc(100% - 32px))" :close-on-click-modal="false" :show-close="!busy" :close-on-press-escape="!busy"><div class="stack"><p>评分 {{stars}} / 5 星</p><p class="preserve">{{comment.trim()}}</p><p>提交后不可修改。双方均提交或评价期结束后公开。</p><p v-if="submitError" class="error" role="alert">{{submitError}}</p><div class="row end"><button class="button" :disabled="busy" @click="confirm=false">返回修改</button><button class="button primary" data-confirm-review :disabled="busy" @click="submit">{{busy?'正在提交…':'确认提交'}}</button></div></div></el-dialog></template>
